(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.012-t*0.15)*15;
  let wy = Math.cos(y*0.015-t*0.18)*20 + Math.sin(x*0.013+t*0.22)*15;
  wx += Math.sin((y+wx)*0.02+t*0.3)*8;
  wy += Math.cos((x+wy)*0.018-t*0.25)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.5)*100, 80+Math.cos(t*0.35)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.6)*50, 0.09, 1.7, 0.8],
    [240+Math.sin(t*0.28+2)*140, 120+Math.cos(t*0.45+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.7+1)*80, 180+Math.sin(t*0.55+3)*60, 0.11, 1.5, 0.9],
    [360+Math.sin(t*0.38+4)*90, 60+Math.cos(t*0.8+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.32+5)*120, 200+Math.sin(t*0.5)*80, 0.08, 1.9, 0.7],
    [80+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65+1)*50, 0.1, 2.1, 0.85],
    [400+Math.cos(t*0.42+2)*60, 200+Math.sin(t*0.48+4)*60, 0.075, 1.8, 1.05]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,amp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*amp;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    cS += Math.cos(d*f*0.5-t*sp*0.4+Math.sin(t*0.3)*2)*amp*0.5;
  }
  const act=aS/8, inh=iS/8, cross=cS/8;
  const bg = (Math.sin(sx*0.035+sy*0.02+t*0.7)+Math.sin(sx*0.028-sy*0.035+t*0.95)+Math.sin(sx*0.05+sy*0.005-t*0.5)*0.5)/2.5+Math.sin((sx+sy)*0.1+t*2.2)*0.15+Math.sin((sx-sy)*0.08-t*1.8)*0.15+Math.sin((sx*0.7-sy*1.3)*0.06+t*1.5)*0.1;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3-t*1.3)+Math.sin(dist*0.038+ang*4.5-t)*0.7+Math.sin(dist*0.06-ang*2+t*0.7)*0.4)*0.35;
  const cellX = Math.sin(sx*0.12+t*0.4)*Math.cos(sy*0.1-t*0.3);
  const cellY = Math.cos(sx*0.1-t*0.35)*Math.sin(sy*0.13+t*0.45);
  const cell = Math.tanh((cellX+cellY+Math.sin((sx+sy)*0.08+t)*0.4)*1.8)*0.3;
  const rawR = act-inh*0.6+bg*0.25+spiral+cross*0.3;
  const reaction = Math.tanh((rawR+Math.sin(rawR*1.5+t*0.8)*0.15)*2.0);
  const fractal = (Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.07-t*1.2)+Math.sin(sx*0.15-t*2)*Math.cos(sy*0.12+t*1.8)*0.5)*0.15;
  const v = (reaction*0.7+cell*0.2+fractal*0.1)*0.5+0.5;
  const pal = [[5,12,52],[12,45,85],[15,85,120],[25,150,145],[120,195,140],[210,200,90],[220,150,75],[195,90,85],[140,50,75],[70,25,60],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.6?1.0+(Math.abs(reaction)-0.6)*0.5:1.0;
  const depth = 0.9+Math.sin(dist*0.02-t*0.5)*0.1;
  const m = lum*edge*depth;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
